package ai.eva.android.probe;
import android.app.*;import android.os.*;import android.content.*;import org.json.*;import java.io.*;
/** Lifecycle acceptance for synthetic local audio/video previews, with muted audio. */
final class DocumentPreviewUiProbe implements Application.ActivityLifecycleCallbacks {
 final Activity owner;final Handler handler=new Handler(Looper.getMainLooper());final JSONObject result=new JSONObject();final String folder;int stage;boolean finished;WorkspacePreviewActivity current;
 DocumentPreviewUiProbe(Activity a,String f){owner=a;folder=f;}
 static void start(Activity a,String folder){if(folder==null||!folder.matches("preview-checks-[a-f0-9]{12}"))return;new DocumentPreviewUiProbe(a,folder).begin();}
 void begin(){owner.getApplication().registerActivityLifecycleCallbacks(this);handler.postDelayed(()->finish(new IOException("Preview UI check timeout, stage "+stage)),15000);open("sample.wav");}
 void open(String file){owner.startActivity(new Intent(owner,WorkspacePreviewActivity.class).putExtra("path",folder+"/"+file));}
 public void onActivityResumed(Activity a){if(!(a instanceof WorkspacePreviewActivity)||finished)return;String path=a.getIntent().getStringExtra("path");if(path==null||!path.startsWith(folder+"/"))return;current=(WorkspacePreviewActivity)a;handler.postDelayed(()->step((WorkspacePreviewActivity)a),100);}
 void require(boolean ok,String why)throws IOException{if(!ok)throw new IOException(why);}
 void step(WorkspacePreviewActivity a){if(finished||a.isDestroyed())return;RichPreview r=a.rich;if(r==null||!r.ready){handler.postDelayed(()->step(a),100);return;}try{if(stage==0){require(r.audio!=null,"Audio surface missing");r.audio.setVolume(0,0);require(!r.audio.isPlaying(),"Audio autoplayed");r.play.performClick();require(r.audio.isPlaying(),"Audio play button failed");stage=1;handler.postDelayed(()->step(a),150);}else if(stage==1){require(r.audio.getCurrentPosition()>0,"Audio timeline did not move");r.pause();require(!r.audio.isPlaying(),"Background pause failed");result.put("audioButtonsAndPause",true);stage=2;a.recreate();}else if(stage==2){require(r.audio!=null&&!r.audio.isPlaying(),"Recreated audio autoplayed");require(r.position>0,"Media position not restored");result.put("audioRecreation",true);stage=3;a.finish();open("sample.webm");}else if(stage==3){require(r.video!=null,"Video surface missing");r.play.performClick();require(r.video.isPlaying(),"Video play button failed");r.pause();require(!r.video.isPlaying(),"Video pause failed");result.put("videoButtonsAndPause",true);finish(null);}}catch(Exception e){finish(e);}}
 void finish(Exception error){if(finished)return;finished=true;handler.removeCallbacksAndMessages(null);owner.getApplication().unregisterActivityLifecycleCallbacks(this);if(current!=null&&!current.isDestroyed())current.finish();try{result.put("passed",error==null);if(error!=null)result.put("error",error.toString());}catch(Exception ignored){}owner.getSharedPreferences("eva-preview-check",0).edit().putString("ui",result.toString()).commit();android.util.Log.i("EvaPreviewUI",result.toString());}
 public void onActivityCreated(Activity a,Bundle b){}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}
}
